#!/usr/bin/env python3
"""Safe callback handshake test. No man's data, password, or real nonce is sent."""
import os
import urllib.request
import urllib.error
import urllib.parse

BASE = "https://dame-camelias.gptjjjgpt.workers.dev"
# Never a real claim: all-zero identifier is not generated by crypto.randomUUID().
PATH = "/api/man-site-login/payload?account_id=yan_second&nonce=" + ("0" * 32)

def probe(label, token=None, explicit_agent=True, agent_name="DameCamelias/CallbackProbe"):
    headers = {"Accept": "application/json"}
    if explicit_agent:
        headers["User-Agent"] = agent_name
    if token:
        headers["Authorization"] = "Bearer " + token
    req = urllib.request.Request(BASE + PATH, headers=headers, method="GET")
    try:
        with urllib.request.urlopen(req, timeout=20) as response:
            code, response_headers = response.status, response.headers
    except urllib.error.HTTPError as ex:
        code, response_headers = ex.code, ex.headers
    except urllib.error.URLError:
        print(f"{label}: network_error", flush=True)
        return None, None
    kind = response_headers.get("Content-Type", "").split(";")[0].strip().lower()
    marker = response_headers.get("X-DC-Callback-Handler", "")
    marker_class = "worker_token_rejected" if marker == "token_rejected" else "none"
    kind_class = "json" if kind == "application/json" else "text" if kind == "text/plain" else "other"
    print(f"{label}: status={code}; kind={kind_class}; marker={marker_class}", flush=True)
    # Do not print the URL, response body, or arbitrary headers.
    return code, marker_class

def main():
    token = os.environ.get("ANKETA_CALLBACK_TOKEN", "")
    print("ACTION_SECRET_INJECTED: " + ("yes" if token else "no"), flush=True)
    noauth, _ = probe("NO_AUTH")
    if not token:
        raise SystemExit("STOP: GitHub Actions callback token is missing")
    default_code, default_marker = probe("WITH_PYTHON_DEFAULT_AGENT", token, explicit_agent=False)
    legacy_code, _ = probe("WITH_YAN_FIRST_AGENT", token, agent_name="DameCameliasBot/1.0")
    yesauth, marker = probe("WITH_ACTIONS_SECRET", token)
    if noauth is None or yesauth is None:
        raise SystemExit("STOP: callback unreachable")
    if yesauth == 409:
        if default_code == 403 and legacy_code == 409:
            print("RESULT: default client denied; Yan First agent accepted", flush=True)
        elif default_code == 403:
            print("RESULT: default client denied while probe agent accepted", flush=True)
        else:
            print("RESULT: token accepted with both client variants; dummy nonce rejected", flush=True)
        return
    if yesauth == 403 and marker == "worker_token_rejected":
        raise SystemExit("RESULT: GitHub callback secret does not match the deployed Worker secret")
    if yesauth == 403:
        raise SystemExit("RESULT: request denied outside identifiable callback token validator")
    raise SystemExit("RESULT: unexpected safe-probe response; needs investigation")

if __name__ == "__main__":
    main()
